                logger.log(
                    "[ECST Causal Control] teacher_loss = "
                    "stopgrad(batch_L1_gradient_match_scalar) * plain_mean_BCE"
                )
                logger.log(
                    "[ECST Causal Control] spatial_weight_positions_used = False"
                )
