                        f"coarse_only_forward_equivalents={2 * num_batches} | "
                        f"gpu_peak_allocated_mb={bitc_peak_allocated_mb:.2f} | "
                        f"gpu_peak_reserved_mb={bitc_peak_reserved_mb:.2f}"
