                            f"{clean_ecst_row['add_conflict_ratio']:.6f} | "
                            "ring_teacher_fg_ratio/ring_teacher_bg_ratio="
                            f"{clean_ecst_row['ring_teacher_fg_ratio']:.6f}/"
                            f"{clean_ecst_row['ring_teacher_bg_ratio']:.6f} | "
