                            f"{clean_ecst_row['semantic_fg_tendency_mean']:.6f}/"
                            f"{clean_ecst_row['history_bg_reliability_mean']:.6f} | "
                            "negative/conflict_weight="
                            f"{clean_ecst_row['negative_weight_mean']:.6f}/"
                            f"{clean_ecst_row['conflict_weight_mean']:.6f} | "
